contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address other, uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(other != address(this), "other must differ from caller");
        require(amount > 0, "amount must be positive");
        require(address(this).balance >= amount, "insufficient test balance");

        c.addToBalance{value: amount}(); if (__ESBMC_reverted()) return;
        uint otherBefore = c.getBalance(other); if (__ESBMC_reverted()) return;

        bool reverted;
        c.withdrawBalance(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        assert(reverted || (c.getBalance(address(this)) == 0 && c.getBalance(other) == otherBefore));
    }

    receive() external payable {}
}

